function monthWeek(weekN: number) {
  const month = Math.ceil(weekN / 4)
  const week = ((weekN - 1) % 4) + 1
  return { month, week, key: month + '-' + week }
}

/** Papers that belong to one teaching week. Logistics keeps a single binder, so it returns nothing here. */
export function papersForWeek(streamId: string, weekN: number): StreamDoc[] {
  const table = streamId === 'construction' ? CONSTRUCTION_WEEK_PAPERS : streamId === 'community' ? COMMUNITY_WEEK_PAPERS : null
  if (!table) return []
  const { month, key } = monthWeek(weekN)
  const docs = [...(table[key] || [])]
  for (const extra of table['month-' + month] || []) {
    if (!docs.some((doc) => doc.href === extra.href)) docs.push(extra)
  }
  if (streamId === 'community' && !docs.some((doc) => doc.title === 'Student workbook')) {
    docs.push({
      title: 'Student workbook',
      href: 'https://drive.google.com/file/d/1awN9DpSWJ8m7mdNS7w8h5xFU4KY393x-/view',
      note: 'Month 1 has no separate weekly workbook file. This is the complete 32-week workbook.',
    })
  }
  return docs
}
